fn is_open(t: &str) -> bool {
    t == "(" || t == "[" || t == "{"
}
fn is_close(t: &str) -> bool {
    t == ")" || t == "]" || t == "}"
}
fn matching_open(close: &str) -> Option<&str> {
    match close {
        ")" => Some("("),
        "]" => Some("["),
        "}" => Some("{"),
        _ => None,
    }
}

fn span_balanced(tokens: &[CodeToken], start_idx: usize, end_idx: usize) -> bool {
    // check tokens[start_idx..end_idx] balanced and never negative
    let mut depth: i32 = 0;
    // need stack for matching types? Simplify: just count overall? Better to use stack for correctness: e.g., "([)]" should be invalid? But such code wouldn't appear in valid code. Simplify to depth counting per type? Use stack.
    let mut stack: Vec<String> = Vec::new();
    for idx in start_idx..end_idx {
        let t = &tokens[idx].text;
        if is_open(t) {
            stack.push(t.clone());
            depth += 1;
        } else if is_close(t) {
            if stack.is_empty() {
                return false; // closes outer
            }
            let open = stack.pop().unwrap();
            let expected = matching_open(t).unwrap();
            if open != expected {
                return false; // mismatched
            }
            depth -= 1;
        }
    }
    stack.is_empty()
}

fn span_has_top_comma(tokens: &[CodeToken], start_idx: usize, end_idx: usize) -> bool {
    let mut depth: i32 = 0;
    let mut stack: Vec<String> = Vec::new();
    for idx in start_idx..end_idx {
        let t = &tokens[idx].text;
        if is_open(t) {
            stack.push(t.clone());
            depth += 1;
        } else if is_close(t) {
            if stack.is_empty() {
                // would be negative, but balanced check already fails; for this check, return true? Actually if unbalanced, caller already rejects. So we can just track.
                depth -= 1;
            } else {
                stack.pop();
                depth -= 1;
            }
        } else if depth == 0 && (t == "," || t == ";") {
            return true;
        }
    }
    false
}

fn tokens_text_equal(a: &[String], b: &[String]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    for (x, y) in a.iter().zip(b.iter()) {
        if x != y {
            return false;
        }
    }
    true
}

