        // Instead of recursion, implement iterative DFS with explicit stack
        // Each state: (pi, ci, single_bindings, multi_bindings, multi_spans, single_ranges)
        // To avoid cloning large maps repeatedly, we can implement recursive function with backtracking and cloning (pattern/code small, so okay).
        if let Some((end_ci, sb, mb, ms, sr)) = match_from(pattern_tokens, code_tokens, 0, start, single_bindings, multi_bindings, multi_spans, single_ranges) {
            // Found match from start to end_ci (exclusive? Actually end_ci is index after last matched token)
            if end_ci > start {
                let start_byte = code_tokens[start].start;
                let end_byte = code_tokens[end_ci - 1].end;
                // Build single_vars: for each named (non-anonymous) single, get last occurrence range (byte offsets)
                let mut single_vars: HashMap<String, (usize, usize)> = HashMap::new();
                for (name, (s_idx, e_idx, _)) in sb.iter() {
                    // s_idx..e_idx are token indices in code_tokens for last occurrence? Actually sb stores last occurrence's token indices? Our match_from updates on each occurrence, so sb holds last.
                    // Convert to byte offsets
                    if *s_idx < *e_idx {
                        let sb_start = code_tokens[*s_idx].start;
                        let sb_end = code_tokens[*e_idx - 1].end;
                        single_vars.insert(name.clone(), (sb_start, sb_end));
                    }
                }
                // For multi: mb holds token ranges? Actually we need to store per-token byte ranges for JSON, and whole span for rewrite.
                // Our match_from for multi stores Vec<(start_byte, end_byte)> per token? Let's see implementation below.
                let mut multi_vars: HashMap<String, Vec<(usize, usize)>> = HashMap::new();
                for (k, v) in mb.iter() {
                    multi_vars.insert(k.clone(), v.clone());
                }
                results.push(MatchResult {
                    start_byte,
                    end_byte,
                    single_vars,
                    multi_vars,
                    multi_spans: ms,
                });
            }
        }
    }
    // Deduplicate? Overlapping matches? Original ast-grep finds all matches, including overlapping? For example, pattern $A matching every node would find many overlapping? But for our simple patterns, overlapping unlikely. Keep as is.
    // Sort by start_byte (already in order)
    results
}

