    // Check bracket balance in pattern tokens (literals only? Vars don't affect?).
    let mut stack: Vec<String> = Vec::new();
    for pt in &tokens {
        if let PatternToken::Literal(lit) = pt {
            if lit == "(" || lit == "[" || lit == "{" {
                stack.push(lit.clone());
            } else if lit == ")" || lit == "]" || lit == "}" {
                if stack.is_empty() {
                    return true;
                }
                let open = stack.pop().unwrap();
                let expected = match lit.as_str() {
                    ")" => "(",
                    "]" => "[",
                    "}" => "{",
                    _ => "",
                };
                if open != expected {
