fn apply_constraints(matches: Vec<MatchResult>, constraints: &Option<HashMap<String, serde_yaml::Value>>, code: &str, code_tokens: &[CodeToken], lang: Lang) -> Vec<MatchResult> {
    if constraints.is_none() {
        return matches;
    }
    let cons = constraints.as_ref().unwrap();
    if cons.is_empty() {
        return matches;
    }
    let mut filtered = Vec::new();
    for m in matches {
        let mut ok = true;
        for (var_name, rule_val) in cons {
            // Find captured text for var_name (could be single or multi?)
            // For single, get range; for multi, get span? Constraints typically on single vars (e.g., $F). For multi, what? Ignore.
            if let Some((s, e)) = m.single_vars.get(var_name) {
                let text = &code[*s..*e];
                // Check rule_val against text
                // Rule_val could be {regex: ...}, {pattern: ...}, {kind: ..., regex: ...}, etc.
                if !check_constraint_rule(rule_val, text, lang) {
                    ok = false;
                    break;
                }
            } else if let Some(ranges) = m.multi_vars.get(var_name) {
                // For multi, what to check? Original constraints on multi? Possibly checks whole span? Use span from multi_spans.
                if let Some(opt) = m.multi_spans.get(var_name) {
                    if let Some((s, e)) = opt {
                        let text = &code[*s..*e];
                        if !check_constraint_rule(rule_val, text, lang) {
                            ok = false;
                            break;
                        }
                    } else {
                        // empty multi, text ""? Check?
                        if !check_constraint_rule(rule_val, "", lang) {
                            ok = false;
                            break;
                        }
                    }
                } else {
                    // anonymous? No check?
                }
            } else {
                // Var not captured (anonymous or missing)? Then constraint fails? Or ignore? Original: if constraint references non-existent var, what? Probably no match. For safety, fail.
                ok = false;
                break;
            }
        }
        if ok {
            filtered.push(m);
        }
    }
    filtered
}

fn check_constraint_rule(rule_val: &serde_yaml::Value, text: &str, lang: Lang) -> bool {
    if let serde_yaml::Value::Mapping(map) = rule_val {
        // If has regex, check regex
        if let Some(re_val) = map.get(serde_yaml::Value::String("regex".to_string())) {
            if let serde_yaml::Value::String(re_str) = re_val {
                if let Ok(re) = regex::Regex::new(re_str) {
                    if !re.is_match(text) {
                        return false;
                    }
                } else {
                    return false;
                }
            }
        }
        // If has pattern, check if text matches pattern (as code snippet)
        if let Some(pat_val) = map.get(serde_yaml::Value::String("pattern".to_string())) {
            let pat_str = match pat_val {
                serde_yaml::Value::String(s) => s.clone(),
                serde_yaml::Value::Mapping(m) => {
                    if let Some(ctx) = m.get(serde_yaml::Value::String("context".to_string())) {
                        if let serde_yaml::Value::String(s) = ctx {
                            s.clone()
                        } else {
                            return false;
                        }
                    } else {
                        return false;
                    }
                }
                _ => return false,
            };
            // Tokenize text as code, pattern as pattern, check if pattern matches entire text? Or if text contains match? Original constraint pattern: does $F text need to match pattern exactly (as a node)? For example, constraint F: {pattern: eval} with $F="eval" should match. Our check: parse pattern, tokenize text, find matches, check if any match spans entire text (from 0 to len)? Or if text contains match?
            // Simplify: check if pattern matches text exactly (one match covering whole text, ignoring whitespace?).
            let pat_tokens = parse_pattern(&pat_str, lang);
            let code_tokens = tokenize_code(text, lang);
            if pat_tokens.is_empty() && code_tokens.is_empty() {
                // both empty? Match?
            } else if pat_tokens.is_empty() || code_tokens.is_empty() {
                return false;
            }
            let matches = find_matches(text, &code_tokens, &pat_tokens);
            // Check if any match covers whole text (start 0, end len, ignoring leading/trailing whitespace? Since tokenization skips whitespace, start_byte of first token might not be 0 if text has leading spaces. But captured text typically has no leading/trailing spaces (since it's from token span). So check if match start==0 and end==len? Or if match text == text (exact)? Let's check exact.
            let mut found = false;
            for m in matches {
                if m.start_byte == 0 && m.end_byte == text.len() {
                    found = true;
                    break;
                }
                // Also allow if match text equals text (trimmed?)? For now, exact.
            }
            if !found {
                return false;
            }
        }
        // If has kind (without pattern/regex)? Without tree-sitter, cannot check kind. For constraint with kind+regex, we already checked regex, ignore kind (treat as pass). For kind alone, what? Return true? Or false? Original constraint with kind alone would check node kind. Without AST, we cannot. For now, return true (pass) to avoid false negatives? But then kind constraint would be ignored. Might cause false positives, but okay.
        // If has any/all/not etc., handle recursively? For simplicity, handle any/all/not with same logic as top-level but on text snippet.
        if let Some(any_val) = map.get(serde_yaml::Value::String("any".to_string())) {
            if let serde_yaml::Value::Sequence(seq) = any_val {
                let mut any_ok = false;
                for sub in seq {
                    if check_constraint_rule(sub, text, lang) {
                        any_ok = true;
                        break;
                    }
                }
                if !any_ok {
                    return false;
                }
            }
        }
        if let Some(all_val) = map.get(serde_yaml::Value::String("all".to_string())) {
            if let serde_yaml::Value::Sequence(seq) = all_val {
                for sub in seq {
                    if !check_constraint_rule(sub, text, lang) {
                        return false;
                    }
                }
            }
        }
        if let Some(not_val) = map.get(serde_yaml::Value::String("not".to_string())) {
            if check_constraint_rule(not_val, text, lang) {
                return false;
            }
        }
        // If no recognized keys, but has kind? Pass? If empty mapping? Pass?
        return true;
    }
    // If rule is not mapping? Return false?
    false
}

