fn handle_scan(m: &ArgMatches, global_config: Option<String>) -> i32 {
    let config = get_scan_config(m, global_config);
    // Load rules
    let mut rules: Vec<RuleConfig> = Vec::new();
    let mut config_dir = ".".to_string();
    let mut is_project = false;
    if let Some(rf) = &config.rule_file {
        match parse_rule_file(rf) {
            Ok(r) => rules.push(r),
            Err(e) => {
                if e.contains("read error") || e.contains("No such") {
                    eprintln!("Error: Cannot read rule {}", rf);
                    eprintln!("Help: The rule file either does not exist or cannot be opened.");
                    eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                    eprintln!();
                    eprintln!("✖ Caused by");
                    eprintln!("╰▻ No such file or directory (os error 2)");
                    eprintln!();
                    return 6;
                } else if e.contains("Rule must specify") {
                    eprintln!("Error: Cannot parse rule {}", rf);
                    eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                    eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                    eprintln!();
                    eprintln!("✖ Caused by");
                    eprintln!("╰▻ {}", e);
                    eprintln!();
                    return 8;
                } else {
                    eprintln!("Error: Cannot parse rule {}", rf);
                    eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                    eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                    eprintln!();
                    eprintln!("✖ Caused by");
                    // e is like "Fail to parse yaml as RuleConfig\n╰▻ ..."
                    for line in e.lines() {
                        if line.starts_with("╰▻") {
                            eprintln!("{}", line);
                        } else {
                            eprintln!("╰▻ {}", line);
                        }
                    }
                    eprintln!();
                    return 8;
                }
            }
        }
    } else if let Some(inline) = &config.inline_rules {
        match parse_inline_rules(inline) {
            Ok(mut rs) => rules.append(&mut rs),
            Err(e) => {
                eprintln!("Error: Cannot parse inline rules");
                eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                eprintln!();
                eprintln!("✖ Caused by");
                eprintln!("╰▻ {}", e.lines().next().unwrap_or(&e));
                for line in e.lines().skip(1) {
                    eprintln!("{}", line);
                }
                eprintln!();
                return 8;
            }
        }
    } else {
        // Load project
        let cfg_path = config.config_file.clone().unwrap_or("sgconfig.yml".to_string());
        // If config_file explicitly given, use it; else search
        let load_path = if config.config_file.is_some() {
            Some(cfg_path.clone())
        } else {
            None // search default
        };
        // Actually load_sgconfig handles search when None? Our load_sgconfig takes Option<String> where None means default? Let's just pass Some("sgconfig.yml") and let it search.
        let search_name = config.config_file.clone().unwrap_or("sgconfig.yml".to_string());
        match load_sgconfig(Some(search_name)) {
            Ok((sg, dir)) => {
                config_dir = dir;
                is_project = true;
                // Discover rules from ruleDirs
                if let Some(dirs) = sg.rule_dirs {
                    for d in dirs {
                        let dir_path = if std::path::Path::new(&d).is_absolute() {
                            PathBuf::from(&d)
                        } else {
                            PathBuf::from(&config_dir).join(&d)
                        };
                        if let Ok(entries) = std::fs::read_dir(&dir_path) {
                            for entry in entries.flatten() {
                                let p = entry.path();
                                if p.is_file() {
                                    if let Some(ext) = p.extension().and_then(|s| s.to_str()) {
                                        if ext == "yml" || ext == "yaml" {
                                            let ps = p.to_string_lossy().to_string();
                                            match parse_rule_file(&ps) {
                                                Ok(r) => rules.push(r),
                                                Err(e) => {
                                                    eprintln!("Error: Cannot parse rule {}", ps);
                                                    eprintln!("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.");
                                                    eprintln!("See also: https://ast-grep.github.io/guide/rule-config.html");
                                                    eprintln!();
                                                    eprintln!("✖ Caused by");
                                                    eprintln!("╰▻ {}", e.lines().next().unwrap_or(&e));
                                                    for line in e.lines().skip(1) {
                                                        eprintln!("{}", line);
                                                    }
                                                    eprintln!();
                                                    return 8;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                } else {
                    // No ruleDirs? Then no rules? Original would error? sgconfig without ruleDirs is invalid? But our SgConfig allows None. If None, treat as no rules (no matches).
                }
                // Apply filter if present
                if let Some(filt) = &config.filter {
                    if let Ok(re) = regex::Regex::new(filt) {
                        rules.retain(|r| re.is_match(&r.id));
                    }
                }
            }
            Err((msg, help, see, code)) => {
                eprintln!("Error: {}", msg);
                eprintln!("Help: {}", help);
                eprintln!("See also: {}", see);
                eprintln!();
                return code;
            }
        }
    }
    // Apply severity overrides and off
    // error/warning/info/hint/off can be empty string (meaning all) or rule IDs
    // If any of them contains "" (from --error without value, default_missing_value ""), then applies to all.
    // Note: our clap for severity uses default_missing_value "" and num_args 0.., so --error without value gives [""].
    let has_all = |v: &Vec<String>| v.iter().any(|s| s.is_empty());
    let error_all = has_all(&config.error);
    let warning_all = has_all(&config.warning);
    let info_all = has_all(&config.info);
    let hint_all = has_all(&config.hint);
    let off_all = has_all(&config.off);
    for r in rules.iter_mut() {
        let id = r.id.clone();
        if config.off.contains(&id) || off_all {
            r.severity = "off".to_string();
        } else if config.error.contains(&id) || error_all {
            r.severity = "error".to_string();
        } else if config.warning.contains(&id) || warning_all {
            r.severity = "warning".to_string();
        } else if config.info.contains(&id) || info_all {
            r.severity = "info".to_string();
        } else if config.hint.contains(&id) || hint_all {
            r.severity = "hint".to_string();
        }
    }
    // Remove off rules (unless? scan should skip off rules)
    rules.retain(|r| r.severity.to_lowercase() != "off");
    // If stdin
    if config.stdin {
        // Read stdin, need to determine lang? For scan with stdin, how to know lang? Each rule has its own lang. For stdin, which lang to use? Original scan --stdin with rule file: it uses rule's lang to parse stdin? Let's see: earlier `echo 'eval("x")' | scan -r rule.yml --stdin` worked (rule lang python, stdin parsed as python). Good. For multiple rules with different langs, stdin would be parsed per rule's lang? Or stdin lang inferred? For scan --stdin, original probably tries each rule's lang? Or requires...? For simplicity, for each rule, parse stdin with rule's lang and match.
        let mut input = String::new();
        std::io::stdin().read_to_string(&mut input).unwrap_or(0);
        let mut diagnostics: Vec<ScanMatch> = Vec::new();
        for rule in &rules {
            let lang_str = rule.language.as_ref().unwrap();
            let lang = Lang::parse(lang_str).unwrap();
            let code_tokens = tokenize_code(&input, lang);
            let mut matches = match_rule_value(&rule.rule, &input, &code_tokens, lang);
            matches = apply_constraints(matches, &rule.constraints, &input, &code_tokens, lang);
            for m in matches {
                diagnostics.push(ScanMatch { file: "STDIN".to_string(), content: input.clone(), lang, rule: rule.clone(), m });
            }
        }
        return output_scan(diagnostics, &config);
    }
    // Discover files (similar to run, but without lang filter initially; filter per rule later)
    let (files, scanned, _) = discover_files(&config.paths, None, config.follow, &config.no_ignore, &config.globs, &config.inspect);
    if config.inspect == "summary" || config.inspect == "entity" {
        eprintln!("sg: summary|project: isProject={}", is_project);
        // entity logs for rules? Original scan inspect entity also logs rules? Let's check: scan --inspect=entity output?
        // For now, just files.
    }
    let mut diagnostics: Vec<ScanMatch> = Vec::new();
    let mut entity_logs: Vec<String> = Vec::new();
    for path in files {
        let mut path_str = path.to_string_lossy().to_string();
        if path_str.starts_with("./") {
            path_str = path_str[2..].to_string();
        }
        let file_lang = Lang::from_path(&path);
        if config.inspect == "entity" {
            if let Some(fl) = file_lang {
                entity_logs.push(format!("sg: entity|file|{}: language={}", path_str, fl.canonical_name()));
            } else {
                entity_logs.push(format!("sg: entity|file|{}: language=None", path_str));
            }
        }
        if file_lang.is_none() {
            continue;
        }
        let fl = file_lang.unwrap();
        // Find rules matching this lang
        let matching_rules: Vec<&RuleConfig> = rules.iter().filter(|r| {
            if let Some(ls) = &r.language {
                if let Some(rl) = Lang::parse(ls) {
                    if rl != fl {
                        return false;
                    }
                } else {
                    return false;
                }
            } else {
                return false;
            }
            // Check files/ignores globs for rule
            if let Some(files_globs) = &r.files {
                // If files specified, file must match at least one? Original files: glob patterns to include. If file doesn't match, skip.
                let mut matched = false;
                for pat in files_globs {
                    if glob_single_match(pat, &path_str, path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default().as_str(), &path) {
                        matched = true;
                        break;
                    }
                }
                if !matched {
                    return false;
                }
            }
            if let Some(ignores) = &r.ignores {
                for pat in ignores {
                    if glob_single_match(pat, &path_str, path.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default().as_str(), &path) {
                        return false;
                    }
                }
            }
            true
        }).collect();
        if matching_rules.is_empty() {
            continue;
        }
        let content_opt = read_file_lossy(&path);
        if content_opt.is_none() {
            continue;
        }
        let content = content_opt.unwrap();
        let code_tokens = tokenize_code(&content, fl);
        for rule in matching_rules {
            let mut matches = match_rule_value(&rule.rule, &content, &code_tokens, fl);
            matches = apply_constraints(matches, &rule.constraints, &content, &code_tokens, fl);
            for m in matches {
                diagnostics.push(ScanMatch { file: path_str.clone(), content: content.clone(), lang: fl, rule: (*rule).clone(), m });
                if let Some(max) = config.max_results {
                    if diagnostics.len() >= max {
                        break;
                    }
                }
            }
            if let Some(max) = config.max_results {
                if diagnostics.len() >= max {
                    break;
                }
            }
        }
        if let Some(max) = config.max_results {
            if diagnostics.len() >= max {
                break;
            }
        }
    }
    if config.inspect == "summary" || config.inspect == "entity" {
        // Already printed project above? Need to print entity logs before results, file summary after? For scan, similar to run.
        // We printed project already, now print entity logs
        if config.inspect == "entity" {
            for log in &entity_logs {
                eprintln!("{}", log);
            }
            // Also log rules? Original scan entity logs rules? Let's probe: scan --inspect=entity
            for r in &rules {
                eprintln!("sg: entity|rule|{}: language={}", r.id, r.language.as_ref().unwrap_or(&"?".to_string()));
            }
        }
    }
    let exit = output_scan(diagnostics, &config);
    if config.inspect == "summary" || config.inspect == "entity" {
        eprintln!("sg: summary|file: scannedFileCount={},skippedFileCount=0", scanned);
