            #[derive(Serialize)]
            struct SarifLocation { #[serde(rename = "physicalLocation")] physical_location: PhysicalLocation }
            #[derive(Serialize)]
            struct PhysicalLocation { #[serde(rename = "artifactLocation")] artifact_location: ArtifactLocation, region: Region }
            #[derive(Serialize)]
            struct ArtifactLocation { uri: String }
            #[derive(Serialize)]
            #[serde(rename_all = "camelCase")]
            struct Region { byte_length: usize, byte_offset: usize, end_column: usize, end_line: usize, snippet: Snippet, start_column: usize, start_line: usize }
            #[derive(Serialize)]
            struct Snippet { text: String }
            #[derive(Serialize)]
            struct SarifMessage { text: String }
            let mut results = Vec::new();
            for d in &diagnostics {
                let (_, sl, sc, el, ec, _, _) = get_lines_info(&d.content, d.m.start_byte, d.m.end_byte);
                let text = d.content[d.m.start_byte..d.m.end_byte].to_string();
                results.push(SarifResult {
                    level: d.rule.severity.to_lowercase(),
                    locations: vec![SarifLocation {
                        physical_location: PhysicalLocation {
                            artifact_location: ArtifactLocation { uri: d.file.clone() },
                            region: Region {
                                byte_length: d.m.end_byte - d.m.start_byte,
                                byte_offset: d.m.start_byte,
                                end_column: ec + 1,
                                end_line: el + 1,
                                snippet: Snippet { text: text.clone() },
                                start_column: sc + 1,
                                start_line: sl + 1,
                            },
                        },
                    }],
                    message: SarifMessage { text: d.rule.message.clone() },
                    rule_id: d.rule.id.clone(),
                });
            }
            let sarif = Sarif {
                runs: vec![SarifRun {
                    results,
                    tool: SarifTool { driver: SarifDriver { name: "ast-grep".to_string() } },
                }],
                version: "0.42.1".to_string(),
            };
            println!("{}", serde_json::to_string_pretty(&sarif).unwrap());
        }
        // After format output, still need error summary and exit code?
        let has_error = diagnostics.iter().any(|d| d.rule.severity.to_lowercase() == "error");
        if has_error {
            let count = diagnostics.iter().filter(|d| d.rule.severity.to_lowercase() == "error").count();
            eprintln!();
            eprintln!("Error: {} error(s) found in code.", count);
            eprintln!("Help: Scan succeeded and found error level diagnostics in the codebase.");
            eprintln!();
            return 1;
        }
        return 0;
    }
    // Normal report styles
    output_scan_inner(diagnostics, config)
}

