fn output_scan_json(diagnostics: Vec<ScanMatch>, config: &ScanConfig) -> i32 {
    use serde::Serialize;
    #[derive(Serialize)]
    #[serde(rename_all = "camelCase")]
    struct ByteOffset { start: usize, end: usize }
    #[derive(Serialize)]
    struct Position { line: usize, column: usize }
    #[derive(Serialize)]
    #[serde(rename_all = "camelCase")]
    struct Range { #[serde(rename = "byteOffset")] byte_offset: ByteOffset, start: Position, end: Position }
    #[derive(Serialize)]
    #[serde(rename_all = "camelCase")]
    struct CharCount { leading: usize, trailing: usize }
    #[derive(Serialize)]
    struct SingleVar { text: String, range: Range }
    #[derive(Serialize)]
    struct MultiVar { text: String, range: Range }
    #[derive(Serialize)]
    struct MetaVars { single: std::collections::BTreeMap<String, SingleVar>, multi: std::collections::BTreeMap<String, Vec<MultiVar>>, transformed: std::collections::BTreeMap<String, String> }
    #[derive(Serialize)]
    struct Label { text: String, range: Range, style: String }
    #[derive(Serialize)]
    #[serde(rename_all = "camelCase")]
    struct JsonScan {
        text: String,
        range: Range,
        file: String,
        lines: String,
        char_count: CharCount,
        language: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        #[serde(rename = "metaVariables")]
        meta_variables: Option<MetaVars>,
        #[serde(rename = "ruleId")]
        rule_id: String,
        severity: String,
        note: Option<String>,
        message: String,
        labels: Vec<Label>,
        #[serde(skip_serializing_if = "Option::is_none")]
        metadata: Option<serde_json::Value>,
    }
    let mut all: Vec<JsonScan> = Vec::new();
    for d in &diagnostics {
        let (lines_text, sl, sc, el, ec, leading, trailing) = get_lines_info(&d.content, d.m.start_byte, d.m.end_byte);
        let range = Range {
            byte_offset: ByteOffset { start: d.m.start_byte, end: d.m.end_byte },
            start: Position { line: sl, column: sc },
            end: Position { line: el, column: ec },
        };
        let meta_variables = if d.m.single_vars.is_empty() && d.m.multi_vars.is_empty() {
            None
        } else {
            let mut single = std::collections::BTreeMap::new();
            for (name, (s, e)) in &d.m.single_vars {
                let (vsl, vsc) = byte_to_line_col(&d.content, *s);
                let (vel, vec_) = byte_to_line_col(&d.content, *e);
                single.insert(name.clone(), SingleVar {
                    text: d.content[*s..*e].to_string(),
                    range: Range {
                        byte_offset: ByteOffset { start: *s, end: *e },
                        start: Position { line: vsl, column: vsc },
                        end: Position { line: vel, column: vec_ },
                    },
                });
            }
            let mut multi = std::collections::BTreeMap::new();
            for (name, ranges) in &d.m.multi_vars {
                let mut arr = Vec::new();
                for (s, e) in ranges {
                    let (vsl, vsc) = byte_to_line_col(&d.content, *s);
                    let (vel, vec_) = byte_to_line_col(&d.content, *e);
                    arr.push(MultiVar {
                        text: d.content[*s..*e].to_string(),
                        range: Range {
                            byte_offset: ByteOffset { start: *s, end: *e },
                            start: Position { line: vsl, column: vsc },
                            end: Position { line: vel, column: vec_ },
                        },
                    });
                }
                multi.insert(name.clone(), arr);
            }
            Some(MetaVars { single, multi, transformed: std::collections::BTreeMap::new() })
        };
        // Labels: default single primary label covering whole match? Original scan json labels: [{"text": ..., "range": ..., "style": "primary"}] with same range as match. Good.
        let labels = vec![Label {
            text: d.content[d.m.start_byte..d.m.end_byte].to_string(),
            range: Range {
                byte_offset: ByteOffset { start: d.m.start_byte, end: d.m.end_byte },
                start: Position { line: sl, column: sc },
                end: Position { line: el, column: ec },
            },
            style: "primary".to_string(),
        }];
        // Metadata? If include_metadata, include rule metadata? What is metadata? Possibly rule's extra fields? For now, None.
        all.push(JsonScan {
            text: d.content[d.m.start_byte..d.m.end_byte].to_string(),
            range,
            file: d.file.clone(),
            lines: lines_text,
            char_count: CharCount { leading, trailing },
            language: d.lang.canonical_name().to_string(),
            meta_variables,
            rule_id: d.rule.id.clone(),
            severity: d.rule.severity.to_lowercase(),
            note: d.rule.note.clone(),
            message: d.rule.message.clone(),
            labels,
            metadata: None,
        });
    }
    // Sort? Already sorted in output_scan_inner? For json, sort similarly.
    // Output based on style
    let style = config.json.as_deref().unwrap_or("pretty");
    match style {
        "stream" => {
            for v in &all {
                println!("{}", serde_json::to_string(v).unwrap());
            }
        }
        "compact" => {
            println!("{}", serde_json::to_string(&all).unwrap());
        }
        _ => {
            if all.is_empty() {
                println!("[]");
            } else {
                println!("[");
                for (i, v) in all.iter().enumerate() {
                    let s = serde_json::to_string_pretty(v).unwrap();
                    if i + 1 < all.len() {
                        println!("{},", s);
                    } else {
                        println!("{}", s);
                    }
                }
                println!("]");
            }
        }
    }
    // Summary and exit code (to stderr, like normal scan)
    let has_error = diagnostics.iter().any(|d| d.rule.severity.to_lowercase() == "error");
    if has_error {
        let count = diagnostics.iter().filter(|d| d.rule.severity.to_lowercase() == "error").count();
        eprintln!("Error: {} error(s) found in code.", count);
        eprintln!("Help: Scan succeeded and found error level diagnostics in the codebase.");
        eprintln!();
        return 1;
    }
    0
}

