    // Simplify: if line counts equal, compare per line.
    let mut out = String::new();
    out.push_str(&format!("@@ -1,{} +1,{} @@\n", exp_lines.len(), act_lines.len()));
    let max_len = exp_lines.len().max(act_lines.len());
    for idx in 0..max_len {
        let e = exp_lines.get(idx);
        let a = act_lines.get(idx);
        match (e, a) {
            (Some(e), Some(a)) => {
                if e == a {
                    out.push_str(&format!("{} {}│ {}\n", idx+1, idx+1, e));
                } else {
                    out.push_str(&format!("{}  │-{}\n", idx+1, e));
                    out.push_str(&format!("  {}│+{}\n", idx+1, a));
                }
            }
            (Some(e), None) => {
                out.push_str(&format!("{}  │-{}\n", idx+1, e));
            }
            (None, Some(a)) => {
                out.push_str(&format!("  {}│+{}\n", idx+1, a));
            }
            (None, None) => {}
        }
    }
