fn generate_snapshot_diff(exp_yaml: &str, act_yaml: &str) -> String {
    // Original diff for snapshot mismatch:
    // @@ -1,4 +1,4 @@
    // 2 2│ - source: eval("bad")
    // 3 3│   style: primary
    // 4 4│   start: 0
    // 5  │-  end: 5
    //   5│+  end: 11
    // This is similar to print_diff format but for YAML lines.
    // exp_yaml and act_yaml are YAML serializations of SnapshotEntry (labels...). Need to split into lines and diff.
    // For simplicity, implement line-by-line diff assuming same line count with some changed lines (like our print_diff for equal lengths).
    let exp_lines: Vec<&str> = exp_yaml.lines().collect();
    let act_lines: Vec<&str> = act_yaml.lines().collect();
    // exp_yaml from serde_yaml::to_string includes "labels:\n- source:..."? Let's see what it looks like. Our entry struct serializes to "labels:\n- source: ...\n  style: ..."? Need to check. Original diff shows lines like "- source: ..." (with -), "  style: ...", etc. Good.
    // For diff, we need to show line numbers? Original diff header "@@ -1,4 +1,4 @@" suggests old start 1, count 4, new start 1, count 4. For our case with 4 lines? Actually exp has 4 lines? Let's just generate similar to print_diff but with YAML lines.
    // Simplify: if line counts equal, compare per line.
    let mut out = String::new();
    out.push_str(&format!("@@ -1,{} +1,{} @@\n", exp_lines.len(), act_lines.len()));
    let max_len = exp_lines.len().max(act_lines.len());
    for idx in 0..max_len {
        let e = exp_lines.get(idx);
        let a = act_lines.get(idx);
        match (e, a) {
            (Some(e), Some(a)) => {
                if e == a {
                    out.push_str(&format!("{} {}│ {}\n", idx+1, idx+1, e));
                } else {
                    out.push_str(&format!("{}  │-{}\n", idx+1, e));
                    out.push_str(&format!("  {}│+{}\n", idx+1, a));
                }
            }
            (Some(e), None) => {
                out.push_str(&format!("{}  │-{}\n", idx+1, e));
            }
            (None, Some(a)) => {
                out.push_str(&format!("  {}│+{}\n", idx+1, a));
            }
            (None, None) => {}
        }
    }
    // Remove trailing newline? Original diff ends without extra blank? Our details format adds "\nFor Code:" after diff, so diff should not end with extra blank. Our out ends with \n, good.
    out.trim_end().to_string()
}

