// ===== Completions handler =====
fn handle_completions(m: &ArgMatches) -> i32 {
    use clap_complete::{generate, shells::{Bash, Elvish, Fish, PowerShell, Zsh}};
    use std::io::BufWriter;
    let shell_opt = m.get_one::<String>("shell").cloned();
    let shell_str = if let Some(s) = shell_opt {
        s
    } else {
        // Infer from SHELL env
        if let Ok(shell_path) = std::env::var("SHELL") {
            let name = std::path::Path::new(&shell_path).file_name().and_then(|s| s.to_str()).unwrap_or("");
            match name {
                "bash" => "bash".to_string(),
                "zsh" => "zsh".to_string(),
                "fish" => "fish".to_string(),
                "elvish" => "elvish".to_string(),
                "powershell" | "pwsh" => "powershell".to_string(),
                _ => {
                    eprintln!("Error: Can not infer which shell to generate completions.");
                    eprintln!("Help: Either specify shell flavor by `sg completions [SHELL]` or set correct `SHELL` environment.");
                    eprintln!("See also: https://ast-grep.github.io/reference/cli.html");
                    eprintln!();
                    return 10;
                }
            }
        } else {
            eprintln!("Error: Can not infer which shell to generate completions.");
            eprintln!("Help: Either specify shell flavor by `sg completions [SHELL]` or set correct `SHELL` environment.");
            eprintln!("See also: https://ast-grep.github.io/reference/cli.html");
            eprintln!();
            return 10;
        }
    };
    let mut cmd = build_top_command();
    // clap_complete generate needs &mut Command
    let mut buf = BufWriter::new(std::io::stdout());
    match shell_str.as_str() {
        "bash" => generate(Bash, &mut cmd, "executable", &mut buf),
        "zsh" => generate(Zsh, &mut cmd, "executable", &mut buf),
        "fish" => generate(Fish, &mut cmd, "executable", &mut buf),
        "elvish" => generate(Elvish, &mut cmd, "executable", &mut buf),
        "powershell" => generate(PowerShell, &mut cmd, "executable", &mut buf),
        _ => {
            eprintln!("Error: Can not infer which shell to generate completions.");
            return 10;
        }
    }
    0
}

